import re
from pathlib import Path

TRAILING = re.compile(rb"[ \t]+(?=\n|\Z)")

for path in sorted(Path("src").rglob("*.py")):
    if not path.is_file():
        continue
    data = path.read_bytes()
    cleaned = TRAILING.sub(b"", data)
    if cleaned != data:
        path.write_bytes(cleaned)
